#include "stdlib/stats/base/ndarray/dztest.h"
#include "stdlib/stats/base/ztest/one-sample/results/float64.h"
#include "stdlib/stats/base/ztest/alternatives.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>

#define NAME "dztest"
#define ITERATIONS 1000000
#define REPEATS 3
#define MIN 1
#define MAX 6

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total ); // TAP plan
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmarks results.
*
* @param iterations  number of iterations
* @param elapsed     elapsed time in seconds
*/
static void print_results( int iterations, double elapsed ) {
	double rate = (double)iterations / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", iterations );
	printf( "  elapsed: %0.9f\n", elapsed );
	printf( "  rate: %0.9f\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Generates a random number on the interval [min,max).
*
* @param min    minimum value (inclusive)
* @param max    maximum value (exclusive)
* @return       random number
*/
static double random_uniform( const double min, const double max ) {
	double v = (double)rand() / ( (double)RAND_MAX + 1.0 );
	return min + ( v*(max-min) );
}

/**
* Runs a benchmark.
*
* @param iterations   number of iterations
* @param len          array length
* @return             elapsed time in seconds
*/
static double benchmark( int iterations, int len ) {
	enum STDLIB_NDARRAY_INDEX_MODE imode;
	const struct ndarray *arrays[ 6 ];
	enum STDLIB_NDARRAY_ORDER order;
	struct ndarray *alpha;
	struct ndarray *sigma;
	int8_t submodes[ 1 ];
	int64_t sstrides[ 1 ];
	int64_t strides[ 1 ];
	struct ndarray *alt;
	struct ndarray *out;
	int64_t shape[ 1 ];
	int64_t nsubmodes;
	struct ndarray *mu;
	struct ndarray *x;
	int64_t offset;
	double elapsed;
	int64_t ndims;
	double *data;
	double t;
	int i;

	struct stdlib_stats_ztest_one_sample_float64_results results = {
		.rejected = false,
		.alpha = 0.0,
		.alternative = STDLIB_STATS_ZTEST_TWO_SIDED,
		.pValue = 0.0,
		.statistic = 0.0,
		.ci = { 0.0, 0.0 },
		.nullValue = 0.0,
		.sd = 0.0
	};
	const int8_t altdata[] = { STDLIB_STATS_ZTEST_TWO_SIDED };
	const double alphadata[] = { 0.05 };
	const double mudata[] = { 0.0 };
	const double sigmadata[] = { 1.0 };

	ndims = 1;
	shape[ 0 ] = len;
	strides[ 0 ] = STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT;
	sstrides[ 0 ] = 0;
	offset = 0;
	order = STDLIB_NDARRAY_ROW_MAJOR;
	imode = STDLIB_NDARRAY_INDEX_ERROR;
	submodes[ 0 ] = imode;
	nsubmodes = 1;

	data = (double *) malloc( len * sizeof( double ) );
	for ( i = 0; i < len; i++ ) {
		data[ i ] = random_uniform( -5.0, 5.0 );
	}
	// cppcheck-suppress invalidPointerCast
	x = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)data, ndims, shape, strides, offset, order, imode, nsubmodes, submodes );
	arrays[ 0 ] = x;

	// cppcheck-suppress invalidPointerCast
	out = stdlib_ndarray_allocate( STDLIB_NDARRAY_USERDEFINED_TYPE, (uint8_t *)&results, 0, NULL, sstrides, 0, order, imode, nsubmodes, submodes );
	arrays[ 1 ] = out;

	// cppcheck-suppress invalidPointerCast
	alt = stdlib_ndarray_allocate( STDLIB_NDARRAY_INT8, (uint8_t *)altdata, 0, NULL, sstrides, 0, order, imode, nsubmodes, submodes );
	arrays[ 2 ] = alt;

	// cppcheck-suppress invalidPointerCast
	alpha = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)alphadata, 0, NULL, sstrides, 0, order, imode, nsubmodes, submodes );
	arrays[ 3 ] = alpha;

	// cppcheck-suppress invalidPointerCast
	mu = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)mudata, 0, NULL, sstrides, 0, order, imode, nsubmodes, submodes );
	arrays[ 4 ] = mu;

	// cppcheck-suppress invalidPointerCast
	sigma = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)sigmadata, 0, NULL, sstrides, 0, order, imode, nsubmodes, submodes );
	arrays[ 5 ] = sigma;

	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		// cppcheck-suppress uninitvar
		stdlib_stats_dztest( arrays );
		if ( results.statistic != results.statistic ) {
			printf( "should not return NaN\n" );
			break;
		}
	}
	elapsed = tic() - t;
	if ( results.statistic != results.statistic ) {
		printf( "should not return NaN\n" );
	}
	stdlib_ndarray_free( x );
	stdlib_ndarray_free( out );
	stdlib_ndarray_free( alt );
	stdlib_ndarray_free( alpha );
	stdlib_ndarray_free( mu );
	stdlib_ndarray_free( sigma );
	free( data );
	arrays[ 0 ] = NULL;
	arrays[ 1 ] = NULL;
	arrays[ 2 ] = NULL;
	arrays[ 3 ] = NULL;
	arrays[ 4 ] = NULL;
	arrays[ 5 ] = NULL;

	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int count;
	int iter;
	int len;
	int i;
	int j;

	// Use the current time to seed the random number generator:
	srand( time( NULL ) );

	print_version();
	count = 0;
	for ( i = MIN; i <= MAX; i++ ) {
		len = pow( 10, i );
		iter = ITERATIONS / pow( 10, i-1 );
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			printf( "# c::%s:len=%d\n", NAME, len );
			elapsed = benchmark( iter, len );
			print_results( iter, elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	print_summary( count, count );
}
